import{_ as a,o as t,c as i,a2 as r}from"./chunks/framework.CDpkVv68.js";const g=JSON.parse('{"title":"Character Creation & Backgrounds","description":"","frontmatter":{},"headers":[],"relativePath":"game-design/characters/character-creation.md","filePath":"game-design/characters/character-creation.md"}'),n={name:"game-design/characters/character-creation.md"};function s(o,e,c,l,d,h){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="character-creation-backgrounds" tabindex="-1">Character Creation &amp; Backgrounds <a class="header-anchor" href="#character-creation-backgrounds" aria-label="Permalink to &quot;Character Creation &amp; Backgrounds&quot;">​</a></h1><p><strong>Design status:</strong> Proposed; open questions remain Unresolved. Referenced Accepted decisions retain their existing scope. <strong>Implementation/availability:</strong> no changes to gameplay or runtime configuration; this redesign is not established as live. <strong>Verification:</strong> documentation review, not a playtest; current availability is not established here. <strong>Reviewed:</strong> 2026-10-09 for public projection; design status and mechanics preserved from the canonical specification.</p><p><a href="/Syrolands-Public/guide/characters/character-creation.html">Player-facing overview</a> · <a href="/Syrolands-Public/game-design/characters/progression.html">Character progression</a></p><h2 id="starting-histories-not-permanent-classes" tabindex="-1">Starting histories, not permanent classes <a class="header-anchor" href="#starting-histories-not-permanent-classes" aria-label="Permalink to &quot;Starting histories, not permanent classes&quot;">​</a></h2><p>Explore creation through <strong>Background → Starting competencies → Initial techniques/knowledge</strong>. A chosen important competency may start around <strong>20 skill</strong>, with fundamentals already known and no initial NPC instruction gate. This is the exception to <a href="/Syrolands-Public/game-design/characters/skills-and-skillcap.html#learning-skills-from-zero-and-teachers">learning an unfamiliar discipline from zero</a>.</p><p>These are histories and competency packages, not permanent classes. Characters remain free to develop in other directions later. Preserve classic creation only where it serves this goal; no exact preset, number of choices or starting-stat allocation is finalized here.</p><h2 id="illustrative-backgrounds" tabindex="-1">Illustrative backgrounds <a class="header-anchor" href="#illustrative-backgrounds" aria-label="Permalink to &quot;Illustrative backgrounds&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Example history</th><th>Candidate competencies</th><th>Candidate initial knowledge</th></tr></thead><tbody><tr><td>Hunter&#39;s Apprentice</td><td>Archery, Tracking, Animal Lore</td><td>Basic field dressing</td></tr><tr><td>Workshop Apprentice</td><td>Carpentry, Tinkering</td><td>Basic joinery</td></tr><tr><td>Village Healer</td><td>Healing, Anatomy</td><td>Basic medical knowledge</td></tr></tbody></table><p>These examples do not approve an exhaustive list, exact skill values per package, free items, reputation or automatic access to all techniques. <a href="/Syrolands-Public/game-design/characters/skills-and-skillcap.html">Skills</a> govern capability; <a href="/Syrolands-Public/game-design/characters/techniques-and-specialization.html">techniques</a> remain separately learned knowledge.</p><h2 id="experience-and-authority-constraints" tabindex="-1">Experience and authority constraints <a class="header-anchor" href="#experience-and-authority-constraints" aria-label="Permalink to &quot;Experience and authority constraints&quot;">​</a></h2><p>Creation should offer an immediately useful identity while explaining that future development is open. The UI should distinguish starting knowledge from numeric capability; it should not promise undiscovered systems or present the examples as finalized classes.</p><p>The client expresses the chosen background and competencies (USER INTENT). The server must validate eligibility and grant the actual stats, skills and knowledge (AUTHORITATIVE SERVER STATE), publish approved values (SYNCHRONIZED STATE), and let the client display the result (CLIENT PRESENTATION). This applies existing server authority; no packets, new UI implementation or save schema are selected.</p><h2 id="legacy-reconciliation" tabindex="-1">Legacy reconciliation <a class="header-anchor" href="#legacy-reconciliation" aria-label="Permalink to &quot;Legacy reconciliation&quot;">​</a></h2><p>Existing character creation has stat totals, per-skill limits, allowed starting skills and item grants; these are not the proposed background model. Numeric 120 in a starting-skill total is not the same as a single skill cap of 120.</p><p>A future implementation must reconcile existing characters, client creation choices and server validation deliberately. No client/server protocol, current character or runtime configuration changes in this batch.</p><h2 id="open-questions" tabindex="-1">Open questions <a class="header-anchor" href="#open-questions" aria-label="Permalink to &quot;Open questions&quot;">​</a></h2><ul><li>How many background/competency choices, and which can be combined?</li><li>Exact initial skill values and whether every chosen competency starts near 20.</li><li>Initial stat values, total stat cap and per-stat ranges; <a href="/Syrolands-Public/game-design/characters/stats.html">stat direction</a> remains separate.</li><li>Whether backgrounds grant techniques, items or reputation, and their custody/persistence.</li><li>Teacher availability/costs for later disciplines and protection against creation/teaching abuse.</li><li>Respec, forgetting or reselecting a history, if supported.</li><li>Legacy-character conversion and when existing production characters matter.</li></ul><p>These questions remain Unresolved; the example packages do not fill the gaps.</p>',18)])])}const u=a(n,[["render",s]]);export{g as __pageData,u as default};
